WF.options=function(){const DEFAULTS={includeOptionsInExport:!1,includeFounderItems:!1,includePvpItems:!1,syncKey:null};return{load:function(){try{const raw=localStorage.getItem("wf_checklist_options");return raw?{...DEFAULTS,...JSON.parse(raw)}:{...DEFAULTS}}catch(err){return console.error("Unreadable or corrupted localStorage options, reset.",err),{...DEFAULTS}}},save:function(optionsMap){try{localStorage.setItem("wf_checklist_options",JSON.stringify(optionsMap))}catch(err){console.error("Failed to save options to localStorage.",err)}},STORAGE_KEY:"wf_checklist_options"}}();